INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Löschanomalie immer vermeidbar ist. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Durch Normalisierung vermeidbar"}, {"text": "Nein", "correct": false, "because": "Mit Normalisierung lösbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, um Löschanomalien in einer Datenbank zu verhindern?', 3, '[{"text": "Normalisierung", "correct": true, "because": "Reduziert Anomalien"}, {"text": "Schnelle Abfragen", "correct": false, "because": "Sekundär"}, {"text": "Bunte Tabellen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren führen zu Löschanomalien?', 5, '[{"text": "Nicht normalisierte Tabellen", "correct": true, "because": "Verursacht Redundanzen"}, {"text": "Fehlende Schlüssel", "correct": true, "because": "Verliert Zusammenhänge"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Datenbankfaktor"}, {"text": "Schnelle Server", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Löschanomalie verliert Daten unbeabsichtigt. b) Sie tritt nur bei großen Datenbanken auf.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch kleine Datenbanken betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Löschanomalien in einer Datenbank vermeiden will?', 4, '[{"text": "Tabellenstruktur", "correct": false, "because": "Entscheidend für Normalisierung"}, {"text": "Fremdschlüssel", "correct": false, "because": "Sichert Beziehungen"}, {"text": "Tabellenfarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Löschanomalie nur beim Löschen auftritt?', 2, '[{"text": "Ja", "correct": true, "because": "Definition der Anomalie"}, {"text": "Nein", "correct": false, "because": "Speziell beim Löschen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich Löschanomalien in einer Datenbank beseitige?', 3, '[{"text": "Datenintegrität", "correct": true, "because": "Verhindert Verlust"}, {"text": "Schnellere Abfragen", "correct": false, "because": "Sekundär"}, {"text": "Weniger Tabellen", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen verhindern Löschanomalien?', 5, '[{"text": "Normalisierung", "correct": true, "because": "Trennt Daten logisch"}, {"text": "Fremdschlüssel", "correct": true, "because": "Sichert Beziehungen"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Datenbankfaktor"}, {"text": "Schnelle Server", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Eine Löschanomalie tritt bei nicht normalisierten Datenbanken auf. b) Sie ist immer absichtlich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unabsichtlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Löschanomalien zu verhindern?', 4, '[{"text": "Datenbanknormalisierung", "correct": false, "because": "Reduziert Anomalien"}, {"text": "Referentielle Integrität", "correct": false, "because": "Sichert Beziehungen"}, {"text": "Farbliche Gestaltung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Tritt eine Löschanomalie nur bei großen Datenbanken auf?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine betroffen"}, {"text": "Ja", "correct": false, "because": "Größe irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Vermeiden von Löschanomalien?', 4, '[{"text": "Datenkonsistenz", "correct": true, "because": "Verhindert Verlust"}, {"text": "Zuverlässige Abfragen", "correct": true, "because": "Sichert Ergebnisse"}, {"text": "Schnellere Server", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Löschanomalien nur bei relationalen Datenbanken auftreten. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Typisch für relationale Modelle"}, {"text": "Nein", "correct": false, "because": "Nur relationale betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Löschanomalien in einer Datenbank zu erkennen?', 3, '[{"text": "Datenbankanalyse", "correct": true, "because": "Zeigt Strukturprobleme"}, {"text": "Schnelle Abfragen", "correct": false, "because": "Nicht primär"}, {"text": "Bunte Diagramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Löschanomalien entstehen durch fehlende Normalisierung. b) Sie betreffen nur Primärschlüssel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht nur Primärschlüssel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich, um Löschanomalien zu vermeiden?', 5, '[{"text": "Tabellenaufteilung", "correct": true, "because": "Normalisiert Daten"}, {"text": "Fremdschlüssel", "correct": true, "because": "Sichert Beziehungen"}, {"text": "Servergeschwindigkeit", "correct": false, "because": "Irrelevant"}, {"text": "Büroausstattung", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Löschanomalien in einer Datenbank prüfe?', 3, '[{"text": "Datenstruktur", "correct": false, "because": "Entscheidend für Analyse"}, {"text": "Beziehungen", "correct": false, "because": "Sichern Integrität"}, {"text": "Tabellenfarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine Löschanomalie durch Normalisierung verhindert werden?', 3, '[{"text": "Ja", "correct": true, "because": "Trennt Daten logisch"}, {"text": "Nein", "correct": false, "because": "Effektiv vermeidbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Löschanomalien die Datenintegrität gefährden?', 2, '[{"text": "Ja", "correct": true, "because": "Verursacht Datenverlust"}, {"text": "Nein", "correct": false, "because": "Integrität betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, um Löschanomalien zu vermeiden?', 4, '[{"text": "Datenbankdesign", "correct": true, "because": "Sichert Struktur"}, {"text": "Schnelle Server", "correct": false, "because": "Irrelevant"}, {"text": "Bunte Visuals", "correct": false, "because": "Ästhetisch"}]');
